// Validation, normalisation et résolution du destinataire.
// Aucune donnée n'est stockée : ce nœud ne fait que nettoyer et router.

const conf = $('Table de routage').first().json;
const b = $('Réception du signalement').first().json.body || {};
const maquette = conf.mode === 'maquette';

const txt = (v, max) => String(v == null ? '' : v).trim().slice(0, max || 500);
const erreurs = [];

// 1. Piège à robots : réponse volontairement neutre
if (txt(b.societe)) {
  return [{ json: { valide: false, silencieux: true, erreurs: ['rejet anti-robot'] } }];
}

const categorie = txt(b.categorie, 80);
const motif = txt(b.motif, 120);
const description = txt(b.description, 1500);
const email = txt(b.email, 120).toLowerCase();
const adresse = txt(b.adresse, 200);
const complement = txt(b.complement, 200);
const nom = txt(b.nom, 80);
const telephone = txt(b.telephone, 24);

const lat = b.latitude === null || b.latitude === undefined ? null : Number(b.latitude);
const lon = b.longitude === null || b.longitude === undefined ? null : Number(b.longitude);
const coordsOk = Number.isFinite(lat) && Number.isFinite(lon)
  && lat > 48.55 && lat < 48.80 && lon > 2.15 && lon < 2.50;

if (!categorie) erreurs.push('Catégorie manquante.');
if (!motif) erreurs.push('Motif manquant.');
if (description.length < 20) erreurs.push('Description trop courte.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) erreurs.push('Adresse e-mail invalide.');
if (b.consentement !== true) erreurs.push('Consentement manquant.');
if (!coordsOk && !adresse) erreurs.push('Localisation manquante.');

const photos = Array.isArray(b.photos) ? b.photos.slice(0, 5) : [];

// 2. Référence : celle de la page si elle est au bon format, sinon régénérée
let reference = txt(b.reference, 20);
if (!/^ESO-\d{6}-\d{6}$/.test(reference)) {
  const d = new Date();
  const p = (n) => String(n).padStart(2, '0');
  reference = 'ESO-' + String(d.getFullYear()).slice(2) + p(d.getMonth() + 1) + p(d.getDate())
    + '-' + p(d.getHours()) + p(d.getMinutes()) + p(d.getSeconds());
}

if (erreurs.length) {
  return [{ json: { valide: false, silencieux: false, reference, erreurs } }];
}

// 3. Routage. En maquette, TOUT converge vers la boîte de test.
const cible = conf.routage[categorie] || conf.defaut;
const destinataire = maquette ? conf.bal_maquette : cible;
const destinataire_usager = maquette ? conf.bal_maquette : email;
const admin = maquette ? conf.bal_maquette : conf.admin;
const archivage = maquette ? '' : conf.archivage;

// 4. Marqueurs visibles en maquette, vides en production
const prefixe_objet = maquette ? '[MAQUETTE] ' : '';
const entete_maquette = maquette
  ? 'ENVOI DE TEST\nEn production, ce message serait adressé à : ' + cible
    + '\nEt l\'accusé de réception à : ' + email + '\n\n---\n\n'
  : '';

// 5. Liens cartographiques
const lienMaps = coordsOk ? 'https://www.google.com/maps/search/?api=1&query=' + lat + ',' + lon : '';
const lienOsm = coordsOk ? 'https://www.openstreetmap.org/?mlat=' + lat + '&mlon=' + lon + '#map=19/' + lat + '/' + lon : '';

return [{
  json: {
    valide: true,
    maquette,
    reference,
    horodatage: b.horodatage || new Date().toISOString(),
    recu_le: new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' }),
    categorie, motif, description,
    adresse: adresse || 'non renseignée',
    complement: complement || '',
    latitude: coordsOk ? lat : null,
    longitude: coordsOk ? lon : null,
    precision_source: txt(b.precision_source, 20) || 'adresse',
    email, nom: nom || 'non renseigné', telephone: telephone || 'non renseigné',
    consentement: true,
    user_agent: txt(b.user_agent, 300),
    cible_production: cible,
    destinataire, destinataire_usager, admin, archivage,
    nom_expediteur: conf.nom_expediteur,
    prefixe_objet, entete_maquette,
    lien_maps: lienMaps,
    lien_osm: lienOsm,
    nb_photos: photos.length,
    photos
  }
}];

// Construction du message complet au format MIME, encodé pour l'API Gmail.
//
// Pourquoi ne pas utiliser le nœud Gmail ici : son champ de pièces jointes est une
// collection à taille fixe. Avec un nombre de photos variable (0 à 5), il retombe sur
// son nom de propriété par défaut et échoue avec « The item has no binary field data ».
// Le message est donc assemblé à la main, puis envoyé par l'API Gmail via HTTP Request.

const d = $input.first().json;
const photos = (d.photos || []).slice(0, 5);

const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const enTete = (s) => '=?UTF-8?B?' + b64(s) + '?=';          // RFC 2047, gère les accents
const plier = (s) => (String(s).match(/.{1,76}/g) || []).join('\r\n');

const limite = 'eso_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);

const objet = d.prefixe_objet + '[SIGNALEMENT ' + d.reference + '] '
  + d.categorie + ' / ' + d.motif + ' - ' + d.adresse;

const corps = d.entete_maquette
  + 'SIGNALEMENT CITOYEN ' + d.reference + '\n'
  + 'Reçu le ' + d.recu_le + '\n\n'
  + 'OBJET\n'
  + 'Catégorie : ' + d.categorie + '\n'
  + 'Motif : ' + d.motif + '\n\n'
  + 'LIEU\n'
  + 'Adresse : ' + d.adresse + '\n'
  + 'Repère : ' + (d.complement || 'non renseigné') + '\n'
  + 'Coordonnées : ' + (d.latitude !== null ? d.latitude + ', ' + d.longitude : 'non renseignées') + '\n'
  + 'Source de la position : ' + d.precision_source + '\n'
  + 'Ouvrir dans Google Maps : ' + (d.lien_maps || 'non disponible') + '\n'
  + 'Ouvrir dans OpenStreetMap : ' + (d.lien_osm || 'non disponible') + '\n\n'
  + 'DESCRIPTION\n' + d.description + '\n\n'
  + 'DÉCLARANT\n'
  + 'E-mail : ' + d.email + '\n'
  + 'Nom : ' + d.nom + '\n'
  + 'Téléphone : ' + d.telephone + '\n\n'
  + 'PHOTOS\n' + photos.length + ' photo(s) en pièce jointe.\n\n'
  + '---\n'
  + 'Message émis automatiquement par le formulaire de signalement du site de la ville.\n'
  + 'Ce courriel est le seul enregistrement du signalement : ne le supprimez pas avant traitement.\n'
  + 'Pour répondre au déclarant, écrivez directement à ' + d.email + '.';

const entetes = [
  'To: ' + d.destinataire,
  'Reply-To: ' + d.email,
  'Subject: ' + enTete(objet),
  'MIME-Version: 1.0',
  'Content-Type: multipart/mixed; boundary="' + limite + '"'
];
if (d.archivage) entetes.splice(1, 0, 'Bcc: ' + d.archivage);

let mime = entetes.join('\r\n') + '\r\n\r\n';

// Corps en base64 : aucun problème d'accent ni de ligne trop longue
mime += '--' + limite + '\r\n'
  + 'Content-Type: text/plain; charset="UTF-8"\r\n'
  + 'Content-Transfer-Encoding: base64\r\n\r\n'
  + plier(b64(corps)) + '\r\n';

// Pièces jointes : autant de parties que de photos réellement présentes
photos.forEach((p, i) => {
  const brut = String(p.donnees || '').replace(/^data:[^,]+,/, '');
  if (!brut) return;
  const nomFichier = ('photo_' + (i + 1) + '.jpg');
  mime += '--' + limite + '\r\n'
    + 'Content-Type: image/jpeg; name="' + nomFichier + '"\r\n'
    + 'Content-Disposition: attachment; filename="' + nomFichier + '"\r\n'
    + 'Content-Transfer-Encoding: base64\r\n\r\n'
    + plier(brut) + '\r\n';
});

mime += '--' + limite + '--';

// base64url, sans remplissage : format attendu par le champ raw de l'API Gmail
const raw = Buffer.from(mime, 'utf8').toString('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

const json = { ...d };
delete json.photos;                 // le payload base64 n'a plus à circuler
json.nb_photos = photos.length;
json.objet = objet;
json.raw = raw;
json.poids_message_ko = Math.round(raw.length * 3 / 4 / 1024);

return [{ json }];

